DROP TABLE IF EXISTS `transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `transactions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `transaction_id` varchar(50) DEFAULT NULL,
  `from_account` varchar(20) DEFAULT NULL,
  `to_account` varchar(20) DEFAULT NULL,
  `amount` decimal(15,2) NOT NULL,
  `type` enum('DEPOSIT','TRANSFER','WITHDRAWAL') NOT NULL,
  `status` enum('COMPLETED','FAILED','PENDING','REVERSED') NOT NULL,
  `timestamp` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `completed_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `failure_reason` varchar(255) DEFAULT NULL,
  `idempotency_key` varchar(100) DEFAULT NULL,
  `transaction_reference` varchar(64) NOT NULL,
  `source_account_id` bigint DEFAULT NULL,
  `target_account_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_transactions_reference` (`transaction_reference`),
  UNIQUE KEY `transaction_id` (`transaction_id`),
  UNIQUE KEY `uk_transactions_idempotency` (`idempotency_key`),
  KEY `idx_transactions_source_acc` (`source_account_id`),
  KEY `idx_transactions_target_acc` (`target_account_id`),
  KEY `idx_transactions_status` (`status`),
  KEY `idx_transactions_created_at` (`created_at`),
  CONSTRAINT `fk_transactions_source_acc` FOREIGN KEY (`source_account_id`) REFERENCES `accounts` (`id`),
  CONSTRAINT `fk_transactions_target_acc` FOREIGN KEY (`target_account_id`) REFERENCES `accounts` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
